:root {
  --ink: #24313d;
  --paper: #fffdf8;
  --line: #d8e2e5;
  --aqua: #bdeee8;
  --aqua-dark: #167d78;
}

* {
  box-sizing: border-box;
}

.laundry-card {
  width: 440px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-head {
  display: flex;
  align-items: center;
  gap: 10px;
}

.machine-icon {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  font-size: 23px;
  background: var(--aqua);
  border-radius: 13px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--aqua-dark);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
}

.card-head h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.1;
}

.status {
  margin-left: auto;
  padding: 5px 9px;
  color: var(--aqua-dark);
  background: var(--aqua);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.cycle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  font-size: 13px;
}

.cycle-row strong {
  font-size: 15px;
}

.start-button {
  padding: 10px 14px;
  display: flex;
  justify-content: space-between;
  color: var(--paper);
  background: var(--aqua-dark);
  border: 0;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 700;
}
